sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {
    var rightNow = new GlideDateTime();

    var overdueTasksAssignedTo = new GlideRecord('x_58872_needit_needit_task');
    overdueTasksAssignedTo.addQuery('due_date', '<=', rightNow);
    overdueTasksAssignedTo.addQuery('state', '<', 3);
    overdueTasksAssignedTo.addQuery('assigned_to', current.assigned_to);

    overdueTasksAssignedTo.query();

    var numberOfOverdues = overdueTasksAssignedTo.getRowCount() - 1;
    if (numberOfOverdues > 0) {
        template.print("In addition to this overdue NeedIt task, you have " + numberOfOverdues + " more overdue NeedIt Tasks.");

    }
    // Add your code here

})(current, template, email, email_action, event);
